use std::{path::Path, process::ExitCode};

use clap::Parser;

// Generated by `build.rs` from `programs/manifest.json`, which is the single
// source of truth for programs to benchmark and test.
include!(concat!(env!("OUT_DIR"), "/programs.rs"));

#[derive(Clone, Copy, clap::ValueEnum)]
enum CompilerArg {
    CargoBuildSbpf,
    CargoBuildSbf,
}

impl From<CompilerArg> for harness::Compiler {
    fn from(value: CompilerArg) -> Self {
        match value {
            CompilerArg::CargoBuildSbpf => Self::CargoBuildSbpf,
            CompilerArg::CargoBuildSbf => Self::CargoBuildSbf,
        }
    }
}
#[derive(Parser)]
struct Arguments {
    #[arg(long, value_enum)]
    compiler: CompilerArg,
}

fn main() -> ExitCode {
    let arguments = Arguments::parse();
    match harness::run(
        Path::new(env!("CARGO_MANIFEST_DIR")),
        arguments.compiler.into(),
        &registrations(),
    ) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::FAILURE
        }
    }
}
